func main() -> int:
    mut source = [1, 2, 3, 4]
    mut kept = [for value in source if value > 2 yield value * 7]
    mut grid = [[1, 2], [3, 4]]
    mut flat: int[] = []
    for row in grid:
        for x in row:
            if x % 2 == 0:
                flat.append(x)
    return kept[0] + kept[1] - 7 + flat[1] - flat[0] - 2

